// Runs one sandboxed trial of the target agent under one fault, and records what
// actually happened: outcome, timing, steps, and the real side effects (refunds,
// emails) taken from the sandbox ledger rather than from the agent's own claims.

import { trace } from 'neatlogs';
import type { Brain } from '../targets/refundbot/agent';
import { ClaudeBrain, SimulatedBrain } from '../targets/refundbot/brains';
import { PaymentsSandbox, sandboxTransport, type Email, type Order, type Refund } from '../targets/refundbot/payments';
import { injectFault, type Fault } from './chaos/faults';
import { mulberry32 } from './stats';
import type { BulwarkTarget } from './target';

export type Outcome = 'completed' | 'crashed' | 'hung' | 'runaway';
export type BrainMode = 'simulated' | 'claude';

export interface TrialObservation {
  seed: number;
  outcome: Outcome;
  error?: string;
  durationMs: number;
  steps: number;
  faultsFired: number;
  reply?: string;
  customerEmail: string;
  orders: Order[];
  refunds: Refund[];
  emails: Email[];
}

export interface TrialOptions {
  target: BulwarkTarget;
  fault?: Fault;
  seed: number;
  brain: BrainMode;
  /** Wall-clock budget before the trial is declared hung. */
  deadlineMs: number;
  /** Safety net so a looping agent can't run forever; exceeding it is a "runaway". */
  maxSteps: number;
}

class StepCapExceeded extends Error {}

export async function runTrial(opts: TrialOptions): Promise<TrialObservation> {
  const { orders, ticket } = opts.target.fixtures();
  const sandbox = new PaymentsSandbox(orders);
  const abort = new AbortController();
  const faultCtx = { rng: mulberry32(opts.seed), signal: abort.signal, fired: 0 };
  const transport = injectFault(sandboxTransport(sandbox, abort.signal), opts.fault, faultCtx);

  const inner: Brain =
    opts.brain === 'claude' ? new ClaudeBrain() : new SimulatedBrain(mulberry32(opts.seed ^ 0x9e3779b9));
  let steps = 0;
  const brain: Brain = {
    name: inner.name,
    decide: async (ctx) => {
      if (abort.signal.aborted) throw new Error('aborted');
      if (++steps > opts.maxSteps) throw new StepCapExceeded(`exceeded ${opts.maxSteps} steps`);
      return inner.decide(ctx);
    },
  };

  return trace(
    {
      name: 'bulwark.trial',
      kind: 'CHAIN',
      attributes: { target: opts.target.name, fault: opts.fault?.id ?? 'none', seed: opts.seed },
    },
    async () => {
      const start = performance.now();
      let outcome: Outcome = 'completed';
      let error: string | undefined;
      let reply: string | undefined;
      let timer: NodeJS.Timeout | undefined;
      const deadline = new Promise<'hung'>((resolve) => {
        timer = setTimeout(() => resolve('hung'), opts.deadlineMs);
      });

      try {
        const res = await Promise.race([opts.target.run(ticket, { transport, brain }), deadline]);
        if (res === 'hung') outcome = 'hung';
        else reply = res.reply;
      } catch (err) {
        outcome = err instanceof StepCapExceeded ? 'runaway' : 'crashed';
        error = err instanceof Error ? err.message : String(err);
      } finally {
        clearTimeout(timer);
        abort.abort();
      }

      return {
        seed: opts.seed,
        outcome,
        error,
        durationMs: performance.now() - start,
        steps: Math.min(steps, opts.maxSteps + 1),
        faultsFired: faultCtx.fired,
        reply,
        customerEmail: ticket.customerEmail,
        orders,
        refunds: [...sandbox.refunds],
        emails: [...sandbox.emails],
      };
    },
  );
}

// Runs N trials per fault and turns them into an honest scorecard: pass rates
// with 95% confidence intervals, outcome breakdowns, and which rules broke.

import { trace } from 'neatlogs';
import type { Fault } from './chaos/faults';
import { runTrial, type BrainMode, type Outcome, type TrialObservation } from './harness';
import { compileRules } from './invariants';
import { hashSeed, percentile, wilson } from './stats';
import type { BulwarkTarget } from './target';

export interface ExperimentResult {
  fault: string;
  title: string;
  hypothesis: string;
  trials: number;
  passed: number;
  passRate: number;
  ci95: [number, number];
  outcomes: Record<Outcome, number>;
  violations: Record<string, number>;
  p95Ms: number;
  /** One failing trial per broken rule, so a human can replay it from its seed. */
  examples: { rule: string; seed: number; detail?: string }[];
}

export interface ExperimentOptions {
  trials: number;
  seed: number;
  brain: BrainMode;
  deadlineMs: number;
  maxSteps: number;
}

export async function runExperiment(
  target: BulwarkTarget,
  fault: Fault | undefined,
  opts: ExperimentOptions,
): Promise<ExperimentResult> {
  const faultId = fault?.id ?? 'baseline';
  const { compiled, uncompiled } = compileRules(target.rules);
  if (uncompiled.length) throw new Error(`could not compile rules: ${uncompiled.join(' | ')}`);

  return trace(
    { name: 'bulwark.experiment', kind: 'WORKFLOW', attributes: { target: target.name, fault: faultId, trials: opts.trials } },
    async () => {
      const observations: TrialObservation[] = await Promise.all(
        Array.from({ length: opts.trials }, (_, i) =>
          runTrial({
            target,
            fault,
            seed: hashSeed(opts.seed, faultId, i),
            brain: opts.brain,
            deadlineMs: opts.deadlineMs,
            maxSteps: opts.maxSteps,
          }),
        ),
      );

      const outcomes: Record<Outcome, number> = { completed: 0, crashed: 0, hung: 0, runaway: 0 };
      const violations: Record<string, number> = Object.fromEntries(compiled.map((c) => [c.rule, 0]));
      const examples: ExperimentResult['examples'] = [];
      let passed = 0;

      for (const obs of observations) {
        outcomes[obs.outcome]++;
        let ok = true;
        for (const { rule, check } of compiled) {
          const res = check(obs);
          if (res.ok) continue;
          ok = false;
          violations[rule]++;
          if (!examples.some((e) => e.rule === rule)) examples.push({ rule, seed: obs.seed, detail: res.detail });
        }
        if (ok) passed++;
      }

      return {
        fault: faultId,
        title: fault?.title ?? 'No fault injected',
        hypothesis: fault?.hypothesis ?? 'The agent works when nothing breaks.',
        trials: opts.trials,
        passed,
        passRate: passed / opts.trials,
        ci95: wilson(passed, opts.trials),
        outcomes,
        violations,
        p95Ms: percentile(observations.map((o) => o.durationMs), 95),
        examples,
      };
    },
  );
}

const pct = (x: number) => `${Math.round(x * 100)}%`;

export function renderMarkdown(target: BulwarkTarget, results: ExperimentResult[], meta: Record<string, unknown>): string {
  const lines = [
    `# Bulwark scorecard: ${target.name}`,
    '',
    Object.entries(meta)
      .map(([k, v]) => `**${k}**: ${v}`)
      .join(' · '),
    '',
    '| Fault | Pass | 95% CI | Crashed | Hung | Runaway | p95 | Broken rules |',
    '|---|---|---|---|---|---|---|---|',
  ];
  for (const r of results) {
    const broken = Object.entries(r.violations)
      .filter(([, n]) => n > 0)
      .map(([rule, n]) => `${rule} (${n})`)
      .join('<br>');
    lines.push(
      `| ${r.fault} | ${r.passed}/${r.trials} | ${pct(r.ci95[0])}–${pct(r.ci95[1])} | ${r.outcomes.crashed} | ${r.outcomes.hung} | ${r.outcomes.runaway} | ${Math.round(r.p95Ms)}ms | ${broken || '—'} |`,
    );
  }
  lines.push('', '## Hypotheses and replayable failures', '');
  for (const r of results) {
    lines.push(`- **${r.fault}**: ${r.hypothesis}`);
    for (const e of r.examples) lines.push(`  - ✗ ${e.rule} → ${e.detail ?? ''} (seed ${e.seed})`);
  }
  return lines.join('\n') + '\n';
}

export function renderConsole(results: ExperimentResult[]): string {
  const rows = results.map((r) => {
    const broken = Object.entries(r.violations)
      .filter(([, n]) => n > 0)
      .map(([rule, n]) => `${n}× ${rule}`)
      .join('; ');
    return [
      r.fault.padEnd(22),
      `${r.passed}/${r.trials}`.padStart(6),
      `${pct(r.ci95[0])}–${pct(r.ci95[1])}`.padEnd(10),
      `crash ${r.outcomes.crashed} hung ${r.outcomes.hung} runaway ${r.outcomes.runaway}`.padEnd(28),
      broken || 'all rules held',
    ].join('  ');
  });
  return [`${'fault'.padEnd(22)}  ${'pass'.padStart(6)}  ${'95% CI'.padEnd(10)}  ${'outcomes'.padEnd(28)}  broken rules`, ...rows].join('\n');
}

import { init, shutdown } from 'neatlogs';

// Traces go to neatlogs when NEATLOGS_API_KEY is set; otherwise spans are still
// created locally but not exported, so everything runs offline.
export async function initTracing(workflowName: string): Promise<boolean> {
  const exporting = Boolean(process.env.NEATLOGS_API_KEY);
  await init({
    apiKey: process.env.NEATLOGS_API_KEY,
    workflowName,
    tags: ['bulwark', 'neatHack'],
    disableExport: !exporting,
  });
  return exporting;
}

export const shutdownTracing = shutdown;

// npm run chaos -- [--fault <id>|all] [--trials 20] [--seed 42] [--brain simulated|claude]
//
// Attacks the target agent with each fault, N trials apiece, and writes a
// scorecard to runs/<timestamp>/.

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseArgs } from 'node:util';
import { target } from '../targets/refundbot/bulwark.target';
import { FAULTS, getFault, type Fault } from './chaos/faults';
import type { BrainMode } from './harness';
import { renderConsole, renderMarkdown, runExperiment, type ExperimentResult } from './scorecard';
import { initTracing, shutdownTracing } from './tracing';

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'all' },
      trials: { type: 'string', default: '20' },
      seed: { type: 'string', default: '42' },
      brain: { type: 'string', default: 'simulated' },
      deadline: { type: 'string', default: '5000' },
      'max-steps': { type: 'string', default: '50' },
    },
  });
  const brain = values.brain as BrainMode;
  if (brain !== 'simulated' && brain !== 'claude') throw new Error('--brain must be "simulated" or "claude"');
  if (brain === 'claude' && !process.env.ANTHROPIC_API_KEY) throw new Error('--brain claude needs ANTHROPIC_API_KEY');

  const faults: (Fault | undefined)[] =
    values.fault === 'all' ? [undefined, ...FAULTS] : [undefined, getFault(values.fault!)];
  const opts = {
    trials: Number(values.trials),
    seed: Number(values.seed),
    brain,
    deadlineMs: Number(values.deadline),
    maxSteps: Number(values['max-steps']),
  };

  const exporting = await initTracing('bulwark-chaos');
  console.log(
    `Bulwark → ${target.name} | ${opts.trials} trials/fault | seed ${opts.seed} | brain ${brain} | neatlogs ${exporting ? 'exporting' : 'local only (no NEATLOGS_API_KEY)'}\n`,
  );

  const results: ExperimentResult[] = [];
  for (const fault of faults) {
    process.stdout.write(`  attacking: ${fault?.id ?? 'baseline'}… `);
    const r = await runExperiment(target, fault, opts);
    console.log(`${r.passed}/${r.trials} passed`);
    results.push(r);
  }
  console.log('\n' + renderConsole(results) + '\n');

  const dir = join('runs', new Date().toISOString().replace(/[:.]/g, '-'));
  mkdirSync(dir, { recursive: true });
  const meta = { trials: opts.trials, seed: opts.seed, brain, date: new Date().toISOString() };
  writeFileSync(join(dir, 'scorecard.json'), JSON.stringify({ target: target.name, ...meta, results }, null, 2));
  writeFileSync(join(dir, 'scorecard.md'), renderMarkdown(target, results, meta));
  console.log(`Scorecard written to ${dir}/`);

  await shutdownTracing();
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { getFault } from '../bulwark/chaos/faults';
import { compileRules } from '../bulwark/invariants';
import { runExperiment } from '../bulwark/scorecard';
import { wilson } from '../bulwark/stats';
import { PaymentsSandbox } from '../targets/refundbot/payments';
import { target } from '../targets/refundbot/bulwark.target';

const opts = { trials: 10, seed: 42, brain: 'simulated' as const, deadlineMs: 2000, maxSteps: 50 };

test('wilson interval matches known values at the extremes', () => {
  const [lo0, hi0] = wilson(0, 20);
  assert.equal(lo0, 0);
  assert.ok(Math.abs(hi0 - 0.161) < 0.001);
  const [lo20, hi20] = wilson(20, 20);
  assert.ok(Math.abs(lo20 - 0.839) < 0.001);
  assert.equal(hi20, 1);
});

test('every RefundBot rule compiles; unknown rules are reported, not skipped', () => {
  assert.equal(compileRules(target.rules).uncompiled.length, 0);
  const { uncompiled } = compileRules(['Always be polite.']);
  assert.deepEqual(uncompiled, ['Always be polite.']);
});

test('sandbox honours idempotency keys', () => {
  const sb = new PaymentsSandbox(target.fixtures().orders);
  sb.createRefund({ orderId: 'ord_1001', amount: 49, idempotencyKey: 'k1' });
  sb.createRefund({ orderId: 'ord_1001', amount: 49, idempotencyKey: 'k1' });
  assert.equal(sb.refunds.length, 1);
});

test('baseline: RefundBot passes every rule when nothing breaks', async () => {
  const r = await runExperiment(target, undefined, opts);
  assert.equal(r.passed, r.trials);
});

test('timeout-after-commit reproduces the double refund, deterministically', async () => {
  const a = await runExperiment(target, getFault('timeout-after-commit'), opts);
  const b = await runExperiment(target, getFault('timeout-after-commit'), opts);
  assert.ok(a.violations['Never refund an order more than once.'] > 0);
  assert.deepEqual(a.violations, b.violations);
});

