// Red agent, step 1: read the target's source and find the weak links, i.e. tool
// calls that can't survive the faults in the catalog. Each finding names the
// file, line and the fault that should trigger it, so every attack starts from
// a hypothesis grounded in the code rather than a random guess.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { FAULTS, type FaultKind } from '../chaos/faults';
import type { BulwarkTarget } from '../target';

export interface Finding {
  kind: FaultKind;
  severity: 'high' | 'medium';
  file: string;
  line: number;
  tool?: string;
  why: string;
  faults: string[];
}

const WRITE_ENDPOINT = /\.(create|send)$/;

function lineOf(src: string, index: number): number {
  return src.slice(0, index).split('\n').length;
}

function faultsFor(kind: FaultKind, endpoint?: string): string[] {
  return FAULTS.filter((f) => f.kind === kind && (!endpoint || f.endpoint === endpoint)).map((f) => f.id);
}

export function analyzeTarget(dir: string, target: BulwarkTarget): Finding[] {
  const findings: Finding[] = [];

  for (const file of target.editableFiles) {
    const src = readFileSync(join(dir, file), 'utf8');

    // Tool definitions: span({ kind: 'TOOL', name: '<tool>' ... }) up to the next tool.
    const toolStarts = [...src.matchAll(/span\(\{ kind: 'TOOL', name: '(\w+)'/g)];
    toolStarts.forEach((m, i) => {
      const start = m.index!;
      const body = src.slice(start, toolStarts[i + 1]?.index ?? src.length);
      const tool = m[1];
      const call = body.match(/transport\('([\w.]+)'/);
      if (!call) return;
      const endpoint = call[1];
      const line = lineOf(src, start + call.index!);
      const writes = WRITE_ENDPOINT.test(endpoint);
      const add = (kind: FaultKind, severity: Finding['severity'], why: string) => {
        const faults = faultsFor(kind, endpoint);
        if (faults.length) findings.push({ kind, severity, file, line, tool, why, faults });
      };

      if (!/withTimeout\(/.test(body)) add('latency', 'medium', `${tool} calls ${endpoint} with no timeout`);
      if (!/withRetry\(/.test(body)) add('rate-limit', 'medium', `${tool} never retries ${endpoint} on transient errors`);
      if (/JSON\.parse\(/.test(body) && !/validate|parse[A-Z]\w*\(/.test(body)) {
        add('malformed', 'medium', `${tool} trusts the JSON from ${endpoint} without validating it`);
      }
      if (writes && /withRetry\(/.test(body) && !/idempotencyKey/.test(body)) {
        add('commit-timeout', 'high', `${tool} retries a money-moving call (${endpoint}) without an idempotency key`);
      }
      if (endpoint === 'policy.search' || /\.text;?\s*$/m.test(body)) {
        if (!/sanitize/i.test(body)) {
          add('injection', 'high', `${tool} passes raw tool output to the model, so injected instructions reach it`);
        }
      }
      if (writes && /amount/.test(body) && !/order\.total|exceeds/.test(body)) {
        add('injection', 'high', `${tool} moves money without checking the amount against the order`);
      }
    });

    const loop = src.match(/while \(true\)/);
    if (loop && !/MAX_STEPS|stepBudget/i.test(src)) {
      findings.push({
        kind: 'loop',
        severity: 'medium',
        file,
        line: lineOf(src, loop.index!),
        why: 'the agent loop has no step budget, so a stuck tool means unbounded steps and cost',
        faults: faultsFor('loop'),
      });
    }
  }

  return findings.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'high' ? -1 : 1));
}

// Sandboxed copies of the target's source. Every fix attempt is materialized in
// its own directory, so a bad patch can never touch the original code, and a
// rejected attempt is thrown away by simply not using its directory again.

import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';

/** File contents keyed by path relative to the target directory. */
export type Files = Record<string, string>;

export function readFiles(dir: string, paths: string[]): Files {
  const files: Files = {};
  for (const p of paths) if (existsSync(join(dir, p))) files[p] = readFileSync(join(dir, p), 'utf8');
  return files;
}

export class Workspace {
  constructor(
    /** Where attempt directories live, e.g. .bulwark/runs/<id>/ws */
    public root: string,
    /** The pristine target directory every attempt starts from. */
    public sourceDir: string,
  ) {
    mkdirSync(root, { recursive: true });
  }

  /** Copies the pristine target, then overlays `files`. Returns the new directory. */
  materialize(label: string, files: Files): string {
    const dir = join(this.root, label);
    rmSync(dir, { recursive: true, force: true });
    cpSync(this.sourceDir, dir, { recursive: true });
    for (const [path, content] of Object.entries(files)) {
      mkdirSync(dirname(join(dir, path)), { recursive: true });
      writeFileSync(join(dir, path), content);
    }
    return dir;
  }
}

/** Unified diff between two file sets, with paths shown relative to the target. */
export function diffFiles(before: Files, after: Files, prefix = ''): string {
  const tmp = mkdtempSync(join(tmpdir(), 'bulwark-diff-'));
  try {
    const out: string[] = [];
    for (const path of [...new Set([...Object.keys(before), ...Object.keys(after)])].sort()) {
      if (before[path] === after[path]) continue;
      const a = join(tmp, 'a');
      const b = join(tmp, 'b');
      writeFileSync(a, before[path] ?? '');
      writeFileSync(b, after[path] ?? '');
      const res = spawnSync('git', ['diff', '--no-index', '--no-color', '-U3', a, b], { encoding: 'utf8' });
      const name = prefix + path;
      out.push(
        res.stdout
          .replace(/^diff --git .*$/m, `diff --git a/${name} b/${name}`)
          .replace(/^--- .*$/m, path in before ? `--- a/${name}` : '--- /dev/null')
          .replace(/^\+\+\+ .*$/m, path in after ? `+++ b/${name}` : '+++ /dev/null')
          .replace(/^(new|deleted) file mode .*\n/m, ''),
      );
    }
    return out.join('');
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

export function diffStats(diff: string): { added: number; removed: number } {
  let added = 0;
  let removed = 0;
  for (const line of diff.split('\n')) {
    if (line.startsWith('+') && !line.startsWith('+++')) added++;
    else if (line.startsWith('-') && !line.startsWith('---')) removed++;
  }
  return { added, removed };
}

// Checkpoints: the exact state of the target's source before each fix attempt,
// plus why it was taken. A rejected fix is undone by restoring the last
// checkpoint, never by trying to "un-edit" a bad patch.
//
// Stored locally under .bulwark/runs/<id>/checkpoints/. Entire checkpoints are
// layered on top once the Entire CLI is installed (see PROJECT_SPEC.md §8).

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { log } from 'neatlogs';
import type { Files } from './workspace';

export interface Checkpoint {
  id: string;
  label: string;
  createdAt: string;
  meta: Record<string, unknown>;
}

export class CheckpointStore {
  private count = 0;

  constructor(private dir: string) {
    mkdirSync(dir, { recursive: true });
  }

  save(label: string, files: Files, meta: Record<string, unknown> = {}): Checkpoint {
    const id = `ckpt-${String(++this.count).padStart(3, '0')}`;
    const cp: Checkpoint = { id, label, createdAt: new Date().toISOString(), meta };
    writeFileSync(join(this.dir, `${id}.json`), JSON.stringify({ ...cp, files }, null, 2));
    log('checkpoint saved: {id} ({label})', { id, label });
    return cp;
  }

  restore(id: string): Files {
    const { files, label } = JSON.parse(readFileSync(join(this.dir, `${id}.json`), 'utf8'));
    log('checkpoint restored: {id} ({label})', { id, label, level: 'warn' });
    return files as Files;
  }
}

// Red agent, step 1: read the target's source and find the weak links, i.e. tool
// calls that can't survive the faults in the catalog. Each finding names the
// file, line and the fault that should trigger it, so every attack starts from
// a hypothesis grounded in the code rather than a random guess.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { FAULTS, type FaultKind } from '../chaos/faults';
import type { BulwarkTarget } from '../target';

export interface Finding {
  kind: FaultKind;
  severity: 'high' | 'medium';
  file: string;
  line: number;
  tool?: string;
  why: string;
  faults: string[];
}

const WRITE_ENDPOINT = /\.(create|send)$/;

function lineOf(src: string, index: number): number {
  return src.slice(0, index).split('\n').length;
}

function faultsFor(kind: FaultKind, endpoint?: string): string[] {
  return FAULTS.filter((f) => f.kind === kind && (!endpoint || f.endpoint === endpoint)).map((f) => f.id);
}

export function analyzeTarget(dir: string, target: BulwarkTarget): Finding[] {
  const findings: Finding[] = [];

  for (const file of target.editableFiles) {
    const src = readFileSync(join(dir, file), 'utf8');

    // Tool definitions: span({ kind: 'TOOL', name: '<tool>' ... }) up to the next tool.
    const toolStarts = [...src.matchAll(/span\(\{ kind: 'TOOL', name: '(\w+)'/g)];
    toolStarts.forEach((m, i) => {
      const start = m.index!;
      const body = src.slice(start, toolStarts[i + 1]?.index ?? src.length);
      const tool = m[1];
      const calls = [...body.matchAll(/transport\('([\w.]+)'/g)];
      if (calls.length === 0) return;
      // The tool's primary call is the one that writes, if any; otherwise its first call.
      const primary = calls.find((c) => WRITE_ENDPOINT.test(c[1])) ?? calls[0];
      const endpoint = primary[1];
      const line = lineOf(src, start + primary.index!);
      const writes = WRITE_ENDPOINT.test(endpoint);
      const add = (kind: FaultKind, severity: Finding['severity'], why: string) => {
        const faults = faultsFor(kind, endpoint);
        if (faults.length) findings.push({ kind, severity, file, line, tool, why, faults });
      };

      if (!/withTimeout\(/.test(body)) add('latency', 'medium', `${tool} calls ${endpoint} with no timeout`);
      if (!/withRetry\(/.test(body)) add('rate-limit', 'medium', `${tool} never retries ${endpoint} on transient errors`);
      if (/JSON\.parse\(/.test(body) && !/validate|parse[A-Z]\w*\(/.test(body)) {
        add('malformed', 'medium', `${tool} trusts the JSON from ${endpoint} without validating it`);
      }
      if (writes && /withRetry\(/.test(body) && !/idempotencyKey/.test(body)) {
        add('commit-timeout', 'high', `${tool} retries a money-moving call (${endpoint}) without an idempotency key`);
      }
      if (/\)\.text\)?;/.test(body) && !/sanitize/i.test(body)) {
        add('injection', 'high', `${tool} passes raw text from ${endpoint} to the model, so injected instructions reach it`);
      }
      if (writes && /amount/.test(body) && !/order\.total/.test(body)) {
        for (const f of faultsFor('injection')) {
          findings.push({
            kind: 'injection',
            severity: 'high',
            file,
            line,
            tool,
            why: `${tool} moves money without checking the amount against the order total`,
            faults: [f],
          });
        }
      }
    });

    const loop = src.match(/while \(true\)/);
    if (loop && !/MAX_STEPS/.test(src)) {
      findings.push({
        kind: 'loop',
        severity: 'medium',
        file,
        line: lineOf(src, loop.index!),
        why: 'the agent loop has no step budget, so a stuck tool means unbounded steps and cost',
        faults: faultsFor('loop'),
      });
    }
  }

  return findings.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'high' ? -1 : 1));
}

